CREATE TABLE public.company_fobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.companies(id), airport_icao text NOT NULL REFERENCES public.airports(icao), base_type text NOT NULL CHECK (base_type IN ('MAIN','SATELLITE')), has_fuel_contract boolean NOT NULL DEFAULT false, has_handling_desk boolean NOT NULL DEFAULT false, has_maintenance_bay boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), next_payment_due timestamptz NOT NULL DEFAULT now()+interval '7 days', closed_at timestamptz);
GRANT SELECT ON public.company_fobs TO authenticated; GRANT ALL ON public.company_fobs TO service_role;
ALTER TABLE public.company_fobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads bases" ON public.company_fobs FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.companies c WHERE c.id=company_id AND c.user_id=auth.uid()));
CREATE UNIQUE INDEX company_fobs_active_airport ON public.company_fobs(company_id,airport_icao) WHERE closed_at IS NULL;
CREATE UNIQUE INDEX company_fobs_one_main ON public.company_fobs(company_id) WHERE closed_at IS NULL AND base_type='MAIN';
ALTER TABLE public.company_ledger DROP CONSTRAINT company_ledger_entry_type_check;
ALTER TABLE public.company_ledger ADD CONSTRAINT company_ledger_entry_type_check CHECK(entry_type IN ('INITIAL_GRANT','LEASE_DEPOSIT','LEASE_PAYMENT','LEASE_DEPOSIT_REFUND','AIRCRAFT_PURCHASE','TICKET_REVENUE','FUEL_EXPENSE','AIRPORT_FEES','HANDLING_FEES','MAINTENANCE_RESERVE','FOB_SETUP','FOB_MODULE','FOB_UPKEEP','RESTRUCTURE_ASSETS','RESTRUCTURE_GRANT'));
CREATE OR REPLACE FUNCTION public.fob_weekly_cost(p_base uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT economy_number(CASE WHEN b.base_type='MAIN' THEN 'fob_main_upkeep' ELSE 'fob_satellite_upkeep' END)+CASE WHEN has_fuel_contract THEN economy_number('fob_fuel_upkeep') ELSE 0 END+CASE WHEN has_handling_desk THEN economy_number('fob_handling_upkeep') ELSE 0 END+CASE WHEN has_maintenance_bay THEN economy_number('fob_maintenance_upkeep') ELSE 0 END FROM company_fobs b JOIN companies c ON c.id=b.company_id WHERE b.id=p_base AND c.user_id=auth.uid() $$;
CREATE OR REPLACE FUNCTION public.process_due_obligations() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c companies%ROWTYPE; b company_fobs%ROWTYPE; cost numeric; bal numeric; BEGIN SELECT * INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RETURN; END IF; PERFORM sync_lease_payments(); bal:=company_balance(c.id); FOR b IN SELECT * FROM company_fobs WHERE company_id=c.id AND closed_at IS NULL ORDER BY next_payment_due,id FOR UPDATE LOOP WHILE b.next_payment_due<=now() LOOP cost:=fob_weekly_cost(b.id); bal:=bal-cost; INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,'FOB_UPKEEP','FOB_EXPENSE','COMPANY_CASH',cost,-cost,bal,'Weekly FOB upkeep – '||b.base_type||' · '||b.airport_icao,b.id::text,'fob:'||b.id||':due:'||b.next_payment_due::text); b.next_payment_due:=b.next_payment_due+interval '7 days'; END LOOP; UPDATE company_fobs SET next_payment_due=b.next_payment_due WHERE id=b.id; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.company_financial_health() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; bal numeric; weekly numeric; debt numeric; status text; nextdue timestamptz; BEGIN SELECT id INTO cid FROM companies WHERE user_id=auth.uid(); IF cid IS NULL THEN RETURN NULL; END IF; bal:=company_balance(cid); SELECT coalesce(sum(k.weekly_rate),0) INTO weekly FROM lease_contracts k JOIN fleet_aircraft f ON f.id=k.aircraft_id WHERE k.company_id=cid AND f.returned_at IS NULL AND f.ownership='LEASED' AND now()>=k.starts_at AND now()<k.ends_at; SELECT weekly+coalesce(sum(fob_weekly_cost(id)),0) INTO weekly FROM company_fobs WHERE company_id=cid AND closed_at IS NULL; SELECT min(due) INTO nextdue FROM (SELECT next_payment_due AS due FROM company_fobs WHERE company_id=cid AND closed_at IS NULL UNION ALL SELECT f.next_payment_due FROM fleet_aircraft f WHERE f.company_id=cid AND f.returned_at IS NULL AND f.ownership='LEASED' AND EXISTS(SELECT 1 FROM lease_contracts k WHERE k.aircraft_id=f.id AND now()<k.ends_at)) x; debt:=greatest(0,-bal); status:=CASE WHEN bal < -economy_number('insolvency_debt_limit') THEN 'INSOLVENT' WHEN bal<0 THEN 'DELINQUENT' WHEN bal<weekly*economy_number('liquidity_buffer_weeks') THEN 'CONSTRAINED' ELSE 'HEALTHY' END; RETURN jsonb_build_object('status',status,'balance',bal,'weekly_obligations',weekly,'debt',debt,'next_payment_due',nextdue); END $$;
CREATE OR REPLACE FUNCTION public.assert_company_investment() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (company_financial_health()->>'status') IN ('DELINQUENT','INSOLVENT') THEN RAISE EXCEPTION 'Outstanding obligations — earn revenue or recover deposits before investing'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.manage_fob(p_action text,p_airport text DEFAULT NULL,p_type text DEFAULT NULL,p_base uuid DEFAULT NULL,p_module text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c companies%ROWTYPE; b company_fobs%ROWTYPE; cost numeric; bal numeric; bid uuid; kind text; label text; BEGIN SELECT * INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No company'; END IF; PERFORM process_due_obligations(); PERFORM assert_company_investment(); bal:=company_balance(c.id); IF p_action='open' THEN IF p_type IS NULL OR p_type NOT IN ('MAIN','SATELLITE') THEN RAISE EXCEPTION 'Choose a base type'; END IF; IF p_type='MAIN' AND EXISTS(SELECT 1 FROM company_fobs WHERE company_id=c.id AND base_type='MAIN' AND closed_at IS NULL) THEN RAISE EXCEPTION 'Only one Main FOB is allowed'; END IF; IF p_type='SATELLITE' AND NOT EXISTS(SELECT 1 FROM company_fobs WHERE company_id=c.id AND base_type='MAIN' AND closed_at IS NULL) THEN RAISE EXCEPTION 'Open your Main FOB first'; END IF; IF p_type='SATELLITE' AND (SELECT count(*) FROM company_fobs WHERE company_id=c.id AND base_type='SATELLITE' AND closed_at IS NULL)>=2 THEN RAISE EXCEPTION 'Maximum two Satellite FOBs'; END IF; cost:=economy_number(CASE WHEN p_type='MAIN' THEN 'fob_main_setup' ELSE 'fob_satellite_setup' END); IF bal<cost THEN RAISE EXCEPTION 'Insufficient Smooth Coins'; END IF; INSERT INTO company_fobs(company_id,airport_icao,base_type) VALUES(c.id,upper(p_airport),p_type) RETURNING * INTO b; kind:='FOB_SETUP'; label:='Open '||p_type||' FOB · '||b.airport_icao; ELSIF p_action='module' THEN SELECT * INTO b FROM company_fobs WHERE id=p_base AND company_id=c.id AND closed_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Base not found'; END IF; IF p_module='fuel' AND NOT b.has_fuel_contract THEN cost:=economy_number('fob_fuel_setup'); UPDATE company_fobs SET has_fuel_contract=true WHERE id=b.id; ELSIF p_module='handling' AND NOT b.has_handling_desk THEN cost:=economy_number('fob_handling_setup'); UPDATE company_fobs SET has_handling_desk=true WHERE id=b.id; ELSIF p_module='maintenance' AND NOT b.has_maintenance_bay THEN cost:=economy_number('fob_maintenance_setup'); UPDATE company_fobs SET has_maintenance_bay=true WHERE id=b.id; ELSE RAISE EXCEPTION 'Invalid or already installed module'; END IF; IF bal<cost THEN RAISE EXCEPTION 'Insufficient Smooth Coins'; END IF; kind:='FOB_MODULE'; label:=p_module||' module · '||b.airport_icao; ELSE RAISE EXCEPTION 'Unknown base action'; END IF; INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,kind,'FOB_ASSET','COMPANY_CASH',cost,-cost,bal-cost,label,b.id::text,'fob:'||b.id||':'||p_action||':'||coalesce(p_module,'setup')); RETURN b.id; END $$;
CREATE OR REPLACE FUNCTION public.reset_airports_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pax_count integer; fuel_count integer; BEGIN IF NOT is_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF EXISTS(SELECT 1 FROM flights WHERE status IN ('DISPATCHED','EN_ROUTE')) THEN RAISE EXCEPTION 'Finish or cancel all active flights before resetting supplies'; END IF; INSERT INTO airport_passenger_pools(airport_icao,stock,updated_at,last_departure_at) SELECT icao,passenger_capacity(icao)*economy_number('initial_stock'),now(),now() FROM airports ON CONFLICT(airport_icao) DO UPDATE SET stock=EXCLUDED.stock,updated_at=EXCLUDED.updated_at,last_departure_at=EXCLUDED.last_departure_at; GET DIAGNOSTICS pax_count=ROW_COUNT; INSERT INTO airport_fuel_pools(airport_icao,fuel_type,stock_gal,updated_at) SELECT a.icao,r.fuel_type,r.capacity_gal*(1+r.development_multiplier*greatest(0,a.development_level-1)),now() FROM airports a JOIN airport_fuel_rules r ON r.size=a.size ON CONFLICT(airport_icao,fuel_type) DO UPDATE SET stock_gal=EXCLUDED.stock_gal,updated_at=EXCLUDED.updated_at; GET DIAGNOSTICS fuel_count=ROW_COUNT; RETURN jsonb_build_object('airports',pax_count,'fuel_pools',fuel_count); END $$;
CREATE OR REPLACE FUNCTION public.restructure_company() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c companies%ROWTYPE; bal numeric; assets numeric; aid uuid:=gen_random_uuid(); capital numeric; BEGIN SELECT * INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No company'; END IF; PERFORM process_due_obligations(); IF company_financial_health()->>'status'<>'INSOLVENT' THEN RAISE EXCEPTION 'Restructuring is only available for insolvent companies'; END IF; IF EXISTS(SELECT 1 FROM flights WHERE company_id=c.id AND status IN ('DISPATCHED','EN_ROUTE')) THEN RAISE EXCEPTION 'Finish or cancel active flights first'; END IF; bal:=company_balance(c.id); SELECT coalesce(sum(CASE WHEN ownership='OWNED' THEN purchase_price ELSE lease_deposit END),0) INTO assets FROM fleet_aircraft WHERE company_id=c.id AND returned_at IS NULL; INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,'RESTRUCTURE_ASSETS','COMPANY_CASH','AIRCRAFT_ASSET',assets,assets,bal+assets,'Restructuring — aircraft liquidation and lease deposit recovery',aid::text,'restructure:'||aid||':assets'); bal:=bal+assets; UPDATE fleet_aircraft SET returned_at=now(),status='RETURNED' WHERE company_id=c.id AND returned_at IS NULL; UPDATE company_fobs SET closed_at=now() WHERE company_id=c.id AND closed_at IS NULL; capital:=economy_number('starting_capital'); INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,'RESTRUCTURE_GRANT',CASE WHEN capital>=bal THEN 'COMPANY_CASH' ELSE 'SYSTEM_TREASURY' END,CASE WHEN capital>=bal THEN 'SYSTEM_TREASURY' ELSE 'COMPANY_CASH' END,abs(capital-bal),capital-bal,capital,'Controlled restructuring — restart capital, history retained',aid::text,'restructure:'||aid||':grant'); END $$;
REVOKE ALL ON FUNCTION public.fob_weekly_cost(uuid),public.process_due_obligations(),public.company_financial_health(),public.assert_company_investment(),public.manage_fob(text,text,text,uuid,text),public.reset_airports_state(),public.restructure_company() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fob_weekly_cost(uuid),public.process_due_obligations(),public.company_financial_health(),public.assert_company_investment(),public.manage_fob(text,text,text,uuid,text),public.reset_airports_state(),public.restructure_company() TO authenticated;